document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll('link[rel="stylesheet"]').forEach(e=>{const t=e.getAttribute("href");t.startsWith("http")&&!t.includes(window.location.hostname)||(e.addEventListener("error",function(){console.error("Failed to load CSS file:",t);const e=document.createElement("link");e.rel="stylesheet",e.href=t+"?reload="+Date.now(),e.setAttribute("nonce",document.querySelector('meta[name="csp-nonce"]')?.getAttribute("content")||""),document.head.appendChild(e)}),e.addEventListener("load",function(){console.log("CSS file loaded successfully:",t)}))}),document.querySelectorAll("style").forEach((e,t)=>{try{const n=e.textContent;if(n){(n.match(/\{/g)||[]).length!==(n.match(/\}/g)||[]).length&&(console.warn(`CSS syntax error in style element ${t}: Mismatched braces`),console.warn("CSS content:",n.substring(0,200)+"..."))}}catch(e){console.error(`Error parsing CSS in style element ${t}:`,e)}})});